// Gated delta-net prefill: scalar decay, delta-rule state, sequential scan.
//
//   for t in 0..T-1:                     (per value head hv)
//     prior_t   = S_t * exp(g[t,hv])
//     pred_t    = prior_t^T k_t
//     S_{t+1}   = prior_t + k_t (beta_t (v_t - pred_t))^T
//     out_t     = S_{t+1}^T q_t
//
// Parallelism: each CTA owns one (value head, value-column block) tile and walks
// T sequentially, holding its state slice in registers.  All K rows of a column
// live in one lane group, so both reductions are warp shuffles.
//
// Decay handling: the state is stored as S / lam with lam = prod(exp(g)).  The
// scalar lam is shared by every element of the tile, so the per-token decay
// costs one multiply per column instead of one per state element.  lam is
// renormalised (state *= lam) whenever it leaves [1e-9, 1e9], which keeps the
// anchored magnitudes inside fp32 range.
#include <torch/extension.h>
#include <c10/cuda/CUDAGuard.h>
#include <c10/cuda/CUDAStream.h>
#include <cuda_runtime.h>
#include <cuda_bf16.h>
#include <cstdint>

namespace {

constexpr int kK = 128;               // key dim
constexpr int kV = 128;               // value dim
constexpr int kHq = 16;               // query heads
constexpr int kHv = 32;               // value heads
constexpr int kRepeat = kHv / kHq;    // grouped-head expansion
constexpr float kL2Eps = 1e-6f;
constexpr float kRsqrtK = 0.08838834764831845f;  // 1/sqrt(128)

constexpr int kVB = 16;               // value columns per tile
constexpr int kRows = 16;             // state rows per thread
constexpr int kGrp = kK / kRows;      // lanes sharing one column
constexpr int kColsWarp = 32 / kGrp;
constexpr int kWarps = kVB / kColsWarp;
constexpr int kThreads = 32 * kWarps;
constexpr int kVBlocks = kV / kVB;
constexpr int kTiles = kHv * kVBlocks;

constexpr float kAnchorLo = 1e-9f;
constexpr float kAnchorHi = 1e9f;

// Normalise one 128-wide row (fp32 math) and optionally rescale it.
__global__ void norm_rows(const __nv_bfloat16* __restrict__ src,
                          float* __restrict__ dst, const float scale,
                          const int nrows) {
  const int r = blockIdx.x * blockDim.x + threadIdx.x;
  if (r >= nrows) return;
  const __nv_bfloat16* row = src + (size_t)r * kK;
  float acc = 0.0f;
#pragma unroll
  for (int i = 0; i < kK; ++i) {
    const float f = __bfloat162float(row[i]);
    acc = fmaf(f, f, acc);
  }
  const float inv = rsqrtf(acc + kL2Eps) * scale;
  float* out = dst + (size_t)r * kK;
#pragma unroll
  for (int i = 0; i < kK; ++i) out[i] = __bfloat162float(row[i]) * inv;
}

// Pack the per-(token, head) scalars so the scan needs a single 8-byte load.
__global__ void pack_scalars(const float* __restrict__ g,
                             const __nv_bfloat16* __restrict__ beta,
                             float2* __restrict__ packed, const int n) {
  const int i = blockIdx.x * blockDim.x + threadIdx.x;
  if (i >= n) return;
  packed[i] = make_float2(expf(g[i]), __bfloat162float(beta[i]));
}

template <int ROWS, int VB>
__global__ void __launch_bounds__(32 * (VB / (32 / (kK / ROWS))))
gdn_scan(const float* __restrict__ qn, const float* __restrict__ kn,
         const __nv_bfloat16* __restrict__ v, const float2* __restrict__ gb,
         const float* __restrict__ h0, __nv_bfloat16* __restrict__ out,
         float* __restrict__ hfin, const int T) {
  constexpr int G = kK / ROWS;          // lanes per column group
  constexpr int COLS_W = 32 / G;        // columns per warp
  constexpr int NVB = kV / VB;

  const int hv = blockIdx.x / NVB;
  const int vb = blockIdx.x % NVB;
  const int hq = hv / kRepeat;

  const int warp = threadIdx.x >> 5;
  const int lane = threadIdx.x & 31;
  const int sub = lane / G;
  const int j = lane % G;
  const int gcol = vb * VB + warp * COLS_W + sub;

  // This thread owns rows 4*G*m + 4*j + i of one value column.
  float st[ROWS];
  {
    const float* p = h0 + ((size_t)hv * kK + 4 * j) * kV + gcol;
#pragma unroll
    for (int m = 0; m < ROWS / 4; ++m) {
#pragma unroll
      for (int i = 0; i < 4; ++i) st[4 * m + i] = p[(size_t)(4 * G * m + i) * kV];
    }
  }

  const __nv_bfloat16* vbase = v + (size_t)hv * kV + gcol;
  __nv_bfloat16* obase = out + (size_t)hv * kV + gcol;
  const float* kbase = kn + (size_t)hq * kK;
  const float* qbase = qn + (size_t)hq * kK;
  const float2* gbase = gb + hv;

  float lam = 1.0f;
  for (int t = 0; t < T; ++t) {
    const float4* k4 = reinterpret_cast<const float4*>(kbase + (size_t)t * kHq * kK);
    const float4* q4 = reinterpret_cast<const float4*>(qbase + (size_t)t * kHq * kK);
    float kk[ROWS], qq[ROWS];
#pragma unroll
    for (int m = 0; m < ROWS / 4; ++m) {
      const float4 ka = k4[G * m + j];
      const float4 qa = q4[G * m + j];
      kk[4 * m + 0] = ka.x; kk[4 * m + 1] = ka.y;
      kk[4 * m + 2] = ka.z; kk[4 * m + 3] = ka.w;
      qq[4 * m + 0] = qa.x; qq[4 * m + 1] = qa.y;
      qq[4 * m + 2] = qa.z; qq[4 * m + 3] = qa.w;
    }

    const float2 gvb = gbase[(size_t)t * kHv];
    lam *= gvb.x;
    if (lam < kAnchorLo || lam > kAnchorHi) {   // renormalise, uniform branch
#pragma unroll
      for (int i = 0; i < ROWS; ++i) st[i] *= lam;
      lam = 1.0f;
    }
    const float inv_lam = __frcp_rn(lam);

    // prediction = (decay * S)^T k, reduced across the row-group lanes
    float a0 = 0.0f, a1 = 0.0f, a2 = 0.0f, a3 = 0.0f;
#pragma unroll
    for (int i = 0; i < ROWS; i += 4) {
      a0 = fmaf(st[i + 0], kk[i + 0], a0);
      a1 = fmaf(st[i + 1], kk[i + 1], a1);
      a2 = fmaf(st[i + 2], kk[i + 2], a2);
      a3 = fmaf(st[i + 3], kk[i + 3], a3);
    }
    float psum = (a0 + a1) + (a2 + a3);
#pragma unroll
    for (int off = G / 2; off > 0; off >>= 1)
      psum += __shfl_xor_sync(0xffffffffu, psum, off, G);

    const float vt = __bfloat162float(vbase[(size_t)t * kHv * kV]);
    const float rs = gvb.y * (vt - lam * psum) * inv_lam;

    // rank-1 state update
#pragma unroll
    for (int i = 0; i < ROWS; ++i) st[i] = fmaf(kk[i], rs, st[i]);

    // output read of the updated state
    float o0 = 0.0f, o1 = 0.0f, o2 = 0.0f, o3 = 0.0f;
#pragma unroll
    for (int i = 0; i < ROWS; i += 4) {
      o0 = fmaf(st[i + 0], qq[i + 0], o0);
      o1 = fmaf(st[i + 1], qq[i + 1], o1);
      o2 = fmaf(st[i + 2], qq[i + 2], o2);
      o3 = fmaf(st[i + 3], qq[i + 3], o3);
    }
    float osum = (o0 + o1) + (o2 + o3);
#pragma unroll
    for (int off = G / 2; off > 0; off >>= 1)
      osum += __shfl_xor_sync(0xffffffffu, osum, off, G);

    if (j == 0) obase[(size_t)t * kHv * kV] = __float2bfloat16(lam * osum);
  }

  {
    float* p = hfin + ((size_t)hv * kK + 4 * j) * kV + gcol;
#pragma unroll
    for (int m = 0; m < ROWS / 4; ++m) {
#pragma unroll
      for (int i = 0; i < 4; ++i) p[(size_t)(4 * G * m + i) * kV] = st[4 * m + i] * lam;
    }
  }
}

void check(const torch::Tensor& t, const torch::ScalarType dt, const int64_t last) {
  TORCH_CHECK_VALUE(t.is_cuda(), "expected CUDA tensor");
  TORCH_CHECK_TYPE(t.scalar_type() == dt, "dtype mismatch");
  TORCH_CHECK_VALUE(t.is_contiguous(), "expected contiguous");
  TORCH_CHECK_VALUE(t.size(t.dim() - 1) == last, "unexpected trailing dim");
}

void kernel(const torch::Tensor& q, const torch::Tensor& k, const torch::Tensor& v,
            const torch::Tensor& g, const torch::Tensor& beta,
            const torch::Tensor& init_state, const torch::Tensor& out,
            const torch::Tensor& final_state) {
  check(q, torch::kBFloat16, kK);
  check(k, torch::kBFloat16, kK);
  check(v, torch::kBFloat16, kV);
  check(g, torch::kFloat32, kHv);
  check(beta, torch::kBFloat16, kHv);
  check(init_state, torch::kFloat32, kV);
  check(out, torch::kBFloat16, kV);
  check(final_state, torch::kFloat32, kV);
  TORCH_CHECK_VALUE(q.size(2) == kHq && v.size(2) == kHv, "head count mismatch");

  const int64_t T = q.size(1);
  TORCH_CHECK_VALUE(v.size(1) == T && g.size(1) == T && out.size(1) == T, "T mismatch");

  c10::cuda::CUDAGuard guard(q.device());
  const cudaStream_t stream = c10::cuda::getCurrentCUDAStream(q.get_device()).stream();

  const int64_t rows = T * kHq;
  torch::Tensor qn = torch::empty({rows, kK}, q.options().dtype(torch::kFloat32));
  torch::Tensor kn = torch::empty({rows, kK}, q.options().dtype(torch::kFloat32));
  torch::Tensor gb = torch::empty({T * kHv, 2}, q.options().dtype(torch::kFloat32));

  const int nb = (int)((rows + 255) / 256);
  norm_rows<<<nb, 256, 0, stream>>>(
      reinterpret_cast<const __nv_bfloat16*>(q.data_ptr<at::BFloat16>()),
      qn.data_ptr<float>(), kRsqrtK, (int)rows);
  norm_rows<<<nb, 256, 0, stream>>>(
      reinterpret_cast<const __nv_bfloat16*>(k.data_ptr<at::BFloat16>()),
      kn.data_ptr<float>(), 1.0f, (int)rows);
  const int np = (int)((T * kHv + 255) / 256);
  pack_scalars<<<np, 256, 0, stream>>>(
      g.data_ptr<float>(),
      reinterpret_cast<const __nv_bfloat16*>(beta.data_ptr<at::BFloat16>()),
      reinterpret_cast<float2*>(gb.data_ptr<float>()), (int)(T * kHv));

  gdn_scan<kRows, kVB><<<kTiles, kThreads, 0, stream>>>(
      qn.data_ptr<float>(), kn.data_ptr<float>(),
      reinterpret_cast<const __nv_bfloat16*>(v.data_ptr<at::BFloat16>()),
      reinterpret_cast<const float2*>(gb.data_ptr<float>()),
      init_state.data_ptr<float>(),
      reinterpret_cast<__nv_bfloat16*>(out.data_ptr<at::BFloat16>()),
      final_state.data_ptr<float>(), (int)T);

  const cudaError_t err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, cudaGetErrorString(err));
}

}  // namespace

PYBIND11_MODULE(TORCH_EXTENSION_NAME, module) { module.def("kernel", &kernel); }

